\documentclass[11pt,a4paper]{ctexart}
\usepackage[margin=2.5cm]{geometry}
\usepackage{amsmath,amssymb}
\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{hyperref}
\hypersetup{colorlinks=true,linkcolor=blue,urlcolor=blue,citecolor=blue}
\usepackage{caption}
\captionsetup{font=small}

\title{@@title@@}
\author{@@author@@\\ \small @@affiliation@@}
\date{@@date@@}

\begin{document}
\maketitle

\begin{abstract}
\noindent\textbf{背景。}% 【写：这个领域为什么重要，1 句】

\noindent\textbf{目标。}% 【写：本文要回答的那个具体问题】

\noindent\textbf{方法。}% 【写：数据、设备/模型、方法名】

\noindent\textbf{结果。}% 【写：必须含数字与对照】

\noindent\textbf{结论。}% 【写：回答问题并说明意义】
\end{abstract}

\noindent\textbf{关键词：} @@keywords@@

\section{引言}
% CARS Move 1：建立研究领域（中心性 + 前人工作）
% CARS Move 2：建立空白（however / few studies / remains unclear）
% CARS Move 3：本文做了什么（we test whether ...）

\section{方法}
% 过去时；数据、设置、流程、统计；保证可复现

\section{结果}
% 过去时；一段一个结论；图题说明结论，图注说明做法
\begin{figure}[htbp]
  \centering
  % \includegraphics[width=0.8\linewidth]{fig/result.pdf}
  \caption{一句结论式的图题}
  \label{fig:main}
\end{figure}

\section{讨论}
% 现在时；结果总结 → 局限 → 与前人比较 → 机制 → 前瞻

\section{结论}
% 回答研究问题、意义、可执行展望；不引入新数据

\begin{thebibliography}{99}
\bibitem{ref1} @@Author@@. @@Title@@. \emph{@@Journal@@}, @@Year@@.
\end{thebibliography}

\end{document}

